1	/**
2	 * TeamConnectionService — gerencia o roster "minha equipe" (Slice 1, R1/R2).
3	 *
4	 * Modelo: aresta bilateral consentida (handshake UMA vez).
5	 * - Empresa adiciona o freela via QR / link / telefone → conexão nasce 'pending'.
6	 * - Freela aceita → 'accepted'. Convites de turno seguintes NÃO re-pedem handshake.
7	 * - Freela pode sair/bloquear → 'blocked'.
8	 *
9	 * Avisos do architect (ADR-001):
10	 * - Criar-turno e aceite NÃO chamam reserve_escrow (postpago é Slice 2).
11	 * - A empresa NÃO pode forjar 'accepted' (RLS WITH CHECK).
12	 * - Envio de SMS para o canal 'phone' é Slice 4 — aqui só criamos o registro.
13	 */
14	
15	import { supabase } from '../lib/supabase';
16	import { logError } from '../lib/logger';
17	import type {
18	  TeamConnection,
19	  TeamConnectionSource,
20	  TeamConnectionStatus,
21	  TeamMember,
22	  MyStore,
23	  WorkerProfile,
24	  CompanyProfile,
25	} from '../types';
26	
27	// ---------------------------------------------------------------------------
28	// Tipos auxiliares internos
29	// ---------------------------------------------------------------------------
30	
31	export interface CreateConnectionResult {
32	  connection: TeamConnection | null;
33	  error?: string;
34	  /** true quando a conexão já existia (idempotência de convite de equipe) */
35	  alreadyExists?: boolean;
36	}
37	
38	export interface UpdateConnectionResult {
39	  success: boolean;
40	  error?: string;
41	}
42	
43	/**
44	 * Token de convite de conexão via link (R1-b).
45	 * Gerado pelo service e armazenado como metadata na conexão.
46	 * Resolução: o link traz o token → service lê a conexão pending → worker aceita.
47	 */
48	export interface ConnectionInviteToken {
49	  token: string;
50	  /** URL pública do link de convite */
51	  url: string;
52	}
53	
54	// ---------------------------------------------------------------------------
55	// Helpers de query de empresa (session)
56	// ---------------------------------------------------------------------------
57	
58	/**
59	 * Retorna o `company_id` da empresa autenticada.
60	 * Lança erro se não houver sessão ou se o usuário não for empresa.
61	 */
62	async function getAuthenticatedCompanyId(): Promise<string> {
63	  const {
64	    data: { user },
65	  } = await supabase.auth.getUser();
66	  if (!user) throw new Error('Sessão expirada. Faça login novamente.');
67	
68	  const { data: company, error } = await supabase
69	    .from('companies')
70	    .select('id')
71	    .eq('owner_id', user.id)
72	    .maybeSingle();
73	
74	  if (error) throw error;
75	  if (!company) throw new Error('Perfil de empresa não encontrado.');
76	
77	  return company.id as string;
78	}
79	
80	// ---------------------------------------------------------------------------
81	// TeamConnectionService
82	// ---------------------------------------------------------------------------
83	
84	export const TeamConnectionService = {
85	  // -------------------------------------------------------------------------
86	  // EMPRESA: adicionar freela à equipe
87	  // -------------------------------------------------------------------------
88	
89	  /**
90	   * Adiciona um worker ao roster da empresa (cria conexão 'pending').
91	   *
92	   * @param workerId  UUID do worker (a câmera/scan é responsabilidade da UI).
93	   * @param source    Canal de origem: 'qr' | 'link' | 'phone'.
94	   *
95	   * Canal 'phone': cria o registro pending; o envio de SMS é Slice 4 (NÃO chamado aqui).
96	   * Canal 'link':  gera um token estável; use `generateInviteToken()` para obter a URL.
97	   * Canal 'qr':    a UI fornece o workerId após decode do QR; apenas cria a conexão.
98	   *
99	   * Idempotente: se a conexão já existir retorna `alreadyExists: true` sem erro.
100	   */
101	  async addToTeam(
102	    workerId: string,
103	    source: TeamConnectionSource,
104	  ): Promise<CreateConnectionResult> {
105	    try {
106	      const companyId = await getAuthenticatedCompanyId();
107	
108	      // Verificar se já existe (idempotência — UNIQUE team_connections_unique_pair)
109	      const { data: existing, error: checkErr } = await supabase
110	        .from('team_connections')
111	        .select('*')
112	        .eq('company_id', companyId)
113	        .eq('worker_id', workerId)
114	        .maybeSingle();
115	
116	      if (checkErr) {
117	        logError('teamConnection.addToTeam.check', checkErr);
118	        return { connection: null, error: 'Erro ao verificar conexão existente.' };
119	      }
120	
121	      if (existing) {
122	        return {
123	          connection: existing as TeamConnection,
124	          alreadyExists: true,
125	        };
126	      }
127	
128	      const { data, error } = await supabase
129	        .from('team_connections')
130	        .insert({
131	          company_id: companyId,
132	          worker_id: workerId,
133	          status: 'pending' as TeamConnectionStatus,
134	          source,
135	        })
136	        .select()
137	        .single();
138	
139	      if (error) {
140	        // Corrida: insert concorrente pode ter criado antes de nós (race condition)
141	        if (error.code === '23505') {
142	          return { connection: null, alreadyExists: true };
143	        }
144	        logError('teamConnection.addToTeam.insert', error);
145	        return { connection: null, error: 'Não foi possível adicionar o freela à equipe.' };
146	      }
147	
148	      return { connection: data as TeamConnection };
149	    } catch (err) {
150	      logError('teamConnection.addToTeam', err);
151	      return {
152	        connection: null,
153	        error: err instanceof Error ? err.message : 'Erro inesperado.',
154	      };
155	    }
156	  },
157	
158	  /**
159	   * Gera um token de convite de link estável para a empresa.
160	   *
161	   * Estratégia: o token é derivado APENAS do `company_id` (base64url),
162	   * portanto é estável entre renders — o link enviado ao freela não muda.
163	   * Segurança real vem do RLS; o token só identifica a empresa do link.
164	   * A UI monta a URL: `https://app.worki.com/convite/{token}`.
165	   * O resolver do link chama `resolveInviteToken(token)` para descobrir a empresa.
166	   */
167	  generateInviteToken(companyId: string): ConnectionInviteToken {
168	    // Token estável: derivado apenas do company_id (sem timestamp).
169	    const token = btoa(companyId).replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');
170	    const url = `${window.location.origin}/convite/${token}`;
171	    return { token, url };
172	  },
173	
174	  /**
175	   * Resolve um token de link de convite → retorna o `company_id`.
176	   * Retorna null se o token for inválido ou malformado.
177	   */
178	  resolveInviteToken(token: string): string | null {
179	    try {
180	      // Reverter base64url → base64 padrão antes de decodificar
181	      const padded = token.replace(/-/g, '+').replace(/_/g, '/');
182	      const companyId = atob(padded);
183	      if (!companyId || companyId.length < 30) return null;
184	      return companyId;
185	    } catch {
186	      return null;
187	    }
188	  },
189	
190	  /**
191	   * Adiciona o worker autenticado à equipe da empresa identificada pelo token de convite.
192	   *
193	   * O `workerId` é derivado da sessão ativa (NÃO aceito por parâmetro) para evitar
194	   * que um worker A passe workerId=B e crie conexão em nome de B sem consentimento.
195	   *
196	   * Fluxo: worker clica no link → chama este método (sem args de identidade) →
197	   * conexão criada como 'pending'; worker aceita via acceptConnection.
198	   *
199	   * @param token  Token de convite da URL (gerado por generateInviteToken).
200	   */
201	  async addToTeamByToken(token: string): Promise<CreateConnectionResult> {
202	    // 1. Resolver empresa a partir do token
203	    const companyId = this.resolveInviteToken(token);
204	    if (!companyId) {
205	      return { connection: null, error: 'Link de convite inválido ou expirado.' };
206	    }
207	
208	    // 2. Derivar workerId da sessão autenticada
209	    const {
210	      data: { user },
211	    } = await supabase.auth.getUser();
212	    if (!user) {
213	      return { connection: null, error: 'Sessão expirada. Faça login antes de aceitar o convite.' };
214	    }
215	    const workerId = user.id;
216	
217	    // 3. Verificar que a empresa existe
218	    const { data: company, error: cErr } = await supabase
219	      .from('companies')
220	      .select('id')
221	      .eq('id', companyId)
222	      .single();
223	
224	    if (cErr || !company) {
225	      return { connection: null, error: 'Empresa do convite não encontrada.' };
226	    }
227	
228	    // 4. Idempotência: verificar se já existe a conexão
229	    const { data: existing } = await supabase
230	      .from('team_connections')
231	      .select('*')
232	      .eq('company_id', companyId)
233	      .eq('worker_id', workerId)
234	      .maybeSingle();
235	
236	    if (existing) {
237	      return { connection: existing as TeamConnection, alreadyExists: true };
238	    }
239	
240	    // 5. Inserir conexão pending
241	    const { data, error } = await supabase
242	      .from('team_connections')
243	      .insert({
244	        company_id: companyId,
245	        worker_id: workerId,
246	        status: 'pending' as TeamConnectionStatus,
247	        source: 'link' as TeamConnectionSource,
248	      })
249	      .select()
250	      .single();
251	
252	    if (error) {
253	      if (error.code === '23505') {
254	        return { connection: null, alreadyExists: true };
255	      }
256	      logError('teamConnection.addToTeamByToken.insert', error);
257	      return { connection: null, error: 'Não foi possível registrar o convite.' };
258	    }
259	
260	    return { connection: data as TeamConnection };
261	  },
262	
263	  // -------------------------------------------------------------------------
264	  // WORKER: aceitar ou bloquear/sair
265	  // -------------------------------------------------------------------------
266	
267	  /**
268	   * Worker aceita uma conexão pendente (pending → accepted).
269	   * Máquina de estados validada aqui: só aceita se status for 'pending'.
270	   */
271	  async acceptConnection(connectionId: string): Promise<UpdateConnectionResult> {
272	    try {
273	      const {
274	        data: { user },
275	      } = await supabase.auth.getUser();
276	      if (!user) return { success: false, error: 'Sessão expirada.' };
277	
278	      // Validar estado atual (máquina de estados no service — ADR-001)
279	      const { data: current, error: fetchErr } = await supabase
280	        .from('team_connections')
281	        .select('id, status, worker_id')
282	        .eq('id', connectionId)
283	        .maybeSingle();
284	
285	      if (fetchErr) {
286	        logError('teamConnection.acceptConnection.fetch', fetchErr);
287	        return { success: false, error: 'Conexão não encontrada.' };
288	      }
289	      if (!current) return { success: false, error: 'Conexão não encontrada.' };
290	      if (current.worker_id !== user.id) {
291	        return { success: false, error: 'Você não é o freela desta conexão.' };
292	      }
293	      if (current.status !== 'pending') {
294	        return {
295	          success: false,
296	          error: `Transição inválida: status atual é '${current.status}', esperado 'pending'.`,
297	        };
298	      }
299	
300	      const { error } = await supabase
301	        .from('team_connections')
302	        .update({
303	          status: 'accepted' as TeamConnectionStatus,
304	          accepted_at: new Date().toISOString(),
305	        })
306	        .eq('id', connectionId)
307	        .eq('worker_id', user.id);
308	
309	      if (error) {
310	        logError('teamConnection.acceptConnection.update', error);
311	        return { success: false, error: 'Erro ao aceitar conexão.' };
312	      }
313	
314	      return { success: true };
315	    } catch (err) {
316	      logError('teamConnection.acceptConnection', err);
317	      return {
318	        success: false,
319	        error: err instanceof Error ? err.message : 'Erro inesperado.',
320	      };
321	    }
322	  },
323	
324	  /**
325	   * Worker sai/bloqueia uma empresa (→ 'blocked').
326	   * Funciona para status 'pending' (recusar convite de equipe) ou 'accepted' (sair).
327	   */
328	  async blockConnection(connectionId: string): Promise<UpdateConnectionResult> {
329	    try {
330	      const {
331	        data: { user },
332	      } = await supabase.auth.getUser();
333	      if (!user) return { success: false, error: 'Sessão expirada.' };
334	
335	      // Validar propriedade (deve ser o worker da conexão)
336	      const { data: current, error: fetchErr } = await supabase
337	        .from('team_connections')
338	        .select('id, status, worker_id')
339	        .eq('id', connectionId)
340	        .maybeSingle();
341	
342	      if (fetchErr || !current) {
343	        logError('teamConnection.blockConnection.fetch', fetchErr);
344	        return { success: false, error: 'Conexão não encontrada.' };
345	      }
346	      if (current.worker_id !== user.id) {
347	        return { success: false, error: 'Você não é o freela desta conexão.' };
348	      }
349	      if (current.status === 'blocked') {
350	        return { success: true }; // já bloqueada — idempotente
351	      }
352	
353	      const { error } = await supabase
354	        .from('team_connections')
355	        .update({
356	          status: 'blocked' as TeamConnectionStatus,
357	          blocked_by: user.id,
358	        })
359	        .eq('id', connectionId)
360	        .eq('worker_id', user.id);
361	
362	      if (error) {
363	        logError('teamConnection.blockConnection.update', error);
364	        return { success: false, error: 'Erro ao bloquear conexão.' };
365	      }
366	
367	      return { success: true };
368	    } catch (err) {
369	      logError('teamConnection.blockConnection', err);
370	      return {
371	        success: false,
372	        error: err instanceof Error ? err.message : 'Erro inesperado.',
373	      };
374	    }
375	  },
376	
377	  // -------------------------------------------------------------------------
378	  // EMPRESA: listar equipe aceita ("minha equipe")
379	  // -------------------------------------------------------------------------
380	
381	  /**
382	   * Lista os membros aceitos da equipe da empresa autenticada.
383	   * Retorna conexões 'accepted' com perfil do worker embutido.
384	   */
385	  async listTeamMembers(): Promise<TeamMember[]> {
386	    try {
387	      const companyId = await getAuthenticatedCompanyId();
388	
389	      const { data, error } = await supabase
390	        .from('team_connections')
391	        .select(
392	          `
393	          *,
394	          worker:workers (
395	            id,
396	            full_name,
397	            avatar_url,
398	            photo_url,
399	            primary_role,
400	            roles,
401	            rating_average,
402	            reviews_count,
403	            completed_jobs_count,
404	            city
405	          )
406	        `,
407	        )
408	        .eq('company_id', companyId)
409	        .eq('status', 'accepted')
410	        .order('accepted_at', { ascending: false });
411	
412	      if (error) {
413	        logError('teamConnection.listTeamMembers', error);
414	        return [];
415	      }
416	
417	      return ((data ?? []) as Array<TeamConnection & { worker: WorkerProfile }>).map(
418	        (row) => ({
419	          connection: {
420	            id: row.id,
421	            company_id: row.company_id,
422	            worker_id: row.worker_id,
423	            status: row.status,
424	            source: row.source,
425	            blocked_by: row.blocked_by,
426	            created_at: row.created_at,
427	            accepted_at: row.accepted_at,
428	            updated_at: row.updated_at,
429	          },
430	          worker: row.worker,
431	        }),
432	      );
433	    } catch (err) {
434	      logError('teamConnection.listTeamMembers', err);
435	      return [];
436	    }
437	  },
438	
439	  /**
440	   * Lista todas as conexões da empresa (pending + accepted + blocked).
