1	/**
2	 * ShiftInviteService — convite push de turno (Slice 1, R5/R7/R8).
3	 *
4	 * Fluxo push: EMPRESA cria application com status='invited' para worker da equipe.
5	 * Fluxo de resposta: WORKER aceita ('accepted') ou recusa ('declined').
6	 *
7	 * Avisos do architect (ADR-001):
8	 * 1. A transição de status do convite (invited → accepted/declined) NÃO é forçada por RLS;
9	 *    validamos a máquina de estados AQUI no service.
10	 * 2. Recusa é NEUTRA (zero punição — R7): só muda status para 'declined'.
11	 * 3. Criar-turno e aceite NÃO chamam reserve_escrow (postpago é Slice 2).
12	 *    accepted aqui = status 'hired' (confirmado no turno) SEM escrow. Slice 2 preenche o gap.
13	 * 4. inserts de review devem passar direction explicitamente — ver ReviewService em types/index.ts.
14	 */
15	
16	import { supabase } from '../lib/supabase';
17	import { invokeFunction } from './api';
18	import { logError } from '../lib/logger';
19	import { TeamConnectionService } from './teamConnectionService';
20	import type {
21	  Application,
22	  ApplicationStatus,
23	  InvitationResponse,
24	} from '../types';
25	
26	// ---------------------------------------------------------------------------
27	// Tipos de parâmetros e resultado
28	// ---------------------------------------------------------------------------
29	
30	/** Janela de expiração do convite em horas (R8). Default = 48h. */
31	const DEFAULT_INVITE_EXPIRY_HOURS = 48;
32	
33	export interface InviteWorkerToShiftOptions {
34	  /** Horas até o convite expirar (default: 48). */
35	  expiresInHours?: number;
36	  /** Mensagem personalizada para a notificação (opcional). */
37	  message?: string;
38	}
39	
40	export interface InviteWorkerResult {
41	  application: Application | null;
42	  error?: string;
43	  /** true quando já existe um convite pendente (idempotência). */
44	  alreadyInvited?: boolean;
45	}
46	
47	export interface RespondToInviteResult {
48	  success: boolean;
49	  error?: string;
50	}
51	
52	// ---------------------------------------------------------------------------
53	// Helpers internos
54	// ---------------------------------------------------------------------------
55	
56	/** Obtém o company_id da sessão autenticada (empresa). */
57	async function getAuthCompanyId(): Promise<string> {
58	  const {
59	    data: { user },
60	  } = await supabase.auth.getUser();
61	  if (!user) throw new Error('Sessão expirada. Faça login novamente.');
62	
63	  const { data: company, error } = await supabase
64	    .from('companies')
65	    .select('id')
66	    .eq('owner_id', user.id)
67	    .maybeSingle();
68	
69	  if (error) throw error;
70	  if (!company) throw new Error('Perfil de empresa não encontrado.');
71	
72	  return company.id as string;
73	}
74	
75	/** Calcula timestamp de expiração. */
76	function calcExpiry(hours: number): string {
77	  const d = new Date();
78	  d.setHours(d.getHours() + hours);
79	  return d.toISOString();
80	}
81	
82	// ---------------------------------------------------------------------------
83	// ShiftInviteService
84	// ---------------------------------------------------------------------------
85	
86	export const ShiftInviteService = {
87	  // -------------------------------------------------------------------------
88	  // EMPRESA: convidar worker para turno
89	  // -------------------------------------------------------------------------
90	
91	  /**
92	   * Convida um worker da equipe para um turno específico.
93	   *
94	   * Pré-condições verificadas:
95	   *  1. O worker é conexão 'accepted' da empresa (R2 — lista fechada).
96	   *  2. Não existe convite ativo (invited) para o mesmo job+worker.
97	   *
98	   * Ações:
99	   *  1. Insere em `applications` com status='invited'.
100	   *  2. Cria notificação in-app (insert em `notifications`).
101	   *  3. Invoca `send-notification` para entrega por e-mail.
102	   *
103	   * Não chama reserve_escrow (Slice 2).
104	   *
105	   * @param jobId    UUID do turno (job).
106	   * @param workerId UUID do worker a convidar.
107	   * @param opts     Opções adicionais.
108	   */
109	  async inviteWorkerToShift(
110	    jobId: string,
111	    workerId: string,
112	    opts: InviteWorkerToShiftOptions = {},
113	  ): Promise<InviteWorkerResult> {
114	    try {
115	      const companyId = await getAuthCompanyId();
116	
117	      // 1. Validar que o worker está na equipe aceita (R2)
118	      const inTeam = await TeamConnectionService.isWorkerInTeam(companyId, workerId);
119	      if (!inTeam) {
120	        return {
121	          application: null,
122	          error:
123	            'O freela não está na sua equipe. Adicione-o primeiro para poder convidar.',
124	        };
125	      }
126	
127	      // 2. Verificar se já existe convite pendente (idempotência)
128	      const { data: existing, error: checkErr } = await supabase
129	        .from('applications')
130	        .select('id, status')
131	        .eq('job_id', jobId)
132	        .eq('worker_id', workerId)
133	        .maybeSingle();
134	
135	      if (checkErr) {
136	        logError('shiftInvite.inviteWorkerToShift.check', checkErr);
137	        return { application: null, error: 'Erro ao verificar convite existente.' };
138	      }
139	
140	      if (existing) {
141	        // Já existe application (qualquer status)
142	        if (existing.status === 'invited') {
143	          return {
144	            application: existing as Application,
145	            alreadyInvited: true,
146	          };
147	        }
148	        return {
149	          application: null,
150	          error: `Já existe uma candidatura para este turno com status '${existing.status}'.`,
151	        };
152	      }
153	
154	      // 3. Calcular expiração
155	      const expiresInHours = opts.expiresInHours ?? DEFAULT_INVITE_EXPIRY_HOURS;
156	      const expiresAt = calcExpiry(expiresInHours);
157	      const now = new Date().toISOString();
158	
159	      // 4. Inserir convite em applications
160	      const { data: application, error: insertErr } = await supabase
161	        .from('applications')
162	        .insert({
163	          job_id: jobId,
164	          worker_id: workerId,
165	          status: 'invited' as ApplicationStatus,
166	          invited_by_company_at: now,
167	          invitation_expires_at: expiresAt,
168	        })
169	        .select()
170	        .single();
171	
172	      if (insertErr) {
173	        if (insertErr.code === '23505') {
174	          return { application: null, alreadyInvited: true };
175	        }
176	        logError('shiftInvite.inviteWorkerToShift.insert', insertErr);
177	        return { application: null, error: 'Não foi possível criar o convite.' };
178	      }
179	
180	      // 5. Notificação in-app (insert direto em notifications)
181	      const { error: notifErr } = await supabase.from('notifications').insert({
182	        user_id: workerId,
183	        type: 'status_change',
184	        title: 'Novo convite de turno',
185	        message:
186	          opts.message ??
187	          'Você recebeu um convite para um turno. Acesse "Convites" para aceitar ou recusar.',
188	        link: `/meus-trabalhos?tab=convites`,
189	      });
190	
191	      if (notifErr) {
192	        // Não bloqueia — a application foi criada; notificação é best-effort
193	        logError('shiftInvite.inviteWorkerToShift.notif', notifErr);
194	      }
195	
196	      // 6. Entrega por e-mail via send-notification (best-effort)
197	      try {
198	        await invokeFunction('send-notification', {
199	          userId: workerId,
200	          type: 'shift_invite',
201	          data: {
202	            jobId,
203	            applicationId: application.id,
204	            expiresAt,
205	          },
206	        });
207	      } catch (emailErr) {
208	        // Edge function falhou — não bloqueia o convite
209	        logError('shiftInvite.inviteWorkerToShift.email', emailErr);
210	      }
211	
212	      return { application: application as Application };
213	    } catch (err) {
214	      logError('shiftInvite.inviteWorkerToShift', err);
215	      return {
216	        application: null,
217	        error: err instanceof Error ? err.message : 'Erro inesperado.',
218	      };
219	    }
220	  },
221	
222	  // -------------------------------------------------------------------------
223	  // WORKER: responder ao convite (aceitar ou recusar)
224	  // -------------------------------------------------------------------------
225	
226	  /**
227	   * Worker responde a um convite de turno.
228	   *
229	   * Máquina de estados (validada aqui — ADR-001):
230	   *   'invited' → 'hired'    (quando accepted)
231	   *   'invited' → 'declined' (quando declined — NEUTRO, zero punição — R7)
232	   *
233	   * NÃO chama reserve_escrow (postpago é Slice 2; Slice 2 adiciona o hook aqui).
234	   *
235	   * @param applicationId UUID da application (convite).
236	   * @param response      'accepted' | 'declined'.
237	   */
238	  async respondToInvite(
239	    applicationId: string,
240	    response: InvitationResponse,
241	  ): Promise<RespondToInviteResult> {
242	    try {
243	      const {
244	        data: { user },
245	      } = await supabase.auth.getUser();
246	      if (!user) return { success: false, error: 'Sessão expirada.' };
247	
248	      // 1. Buscar application atual (validar máquina de estados)
249	      const { data: current, error: fetchErr } = await supabase
250	        .from('applications')
251	        .select('id, status, worker_id, invited_by_company_at, invitation_expires_at')
252	        .eq('id', applicationId)
253	        .maybeSingle();
254	
255	      if (fetchErr) {
256	        logError('shiftInvite.respondToInvite.fetch', fetchErr);
257	        return { success: false, error: 'Convite não encontrado.' };
258	      }
259	      if (!current) return { success: false, error: 'Convite não encontrado.' };
260	      if (current.worker_id !== user.id) {
261	        return { success: false, error: 'Este convite não é para você.' };
262	      }
263	      if (current.status !== 'invited') {
264	        return {
265	          success: false,
266	          error: `Transição inválida: status atual é '${current.status}', esperado 'invited'.`,
267	        };
268	      }
269	
270	      // 2. Verificar expiração (R8)
271	      if (current.invitation_expires_at) {
272	        const expiresAt = new Date(current.invitation_expires_at as string);
273	        if (expiresAt < new Date()) {
274	          return {
275	            success: false,
276	            error: 'Este convite expirou. O operador precisará reenviar um novo convite.',
277	          };
278	        }
279	      }
280	
281	      // 3. Mapear response → status final
282	      //    accepted → 'hired' (turno confirmado para os dois lados — sem escrow neste slice)
283	      //    declined → 'declined' (neutro — R7)
284	      const newStatus: ApplicationStatus = response === 'accepted' ? 'hired' : 'declined';
285	      const now = new Date().toISOString();
286	
287	      const { error: updateErr } = await supabase
288	        .from('applications')
289	        .update({
290	          status: newStatus,
291	          invitation_response: response,
292	          invitation_responded_at: now,
293	        })
294	        .eq('id', applicationId)
295	        .eq('worker_id', user.id);
296	
297	      if (updateErr) {
298	        logError('shiftInvite.respondToInvite.update', updateErr);
299	        return { success: false, error: 'Erro ao registrar resposta.' };
300	      }
301	
302	      // 4. Notificação in-app para a empresa (best-effort)
303	      if (response === 'accepted') {
304	        // Buscar company para notificar o operador
305	        const { data: job } = await supabase
306	          .from('applications')
307	          .select('job:jobs(company_id)')
308	          .eq('id', applicationId)
309	          .maybeSingle();
310	
311	        // job.job é um objeto com company_id
312	        const companyId = (job?.job as { company_id?: string } | null)?.company_id;
313	
314	        if (companyId) {
315	          // Buscar owner da empresa
316	          const { data: company } = await supabase
317	            .from('companies')
318	            .select('owner_id')
319	            .eq('id', companyId)
320	            .maybeSingle();
321	
322	          if (company?.owner_id) {
323	            const { error: notifErr } = await supabase.from('notifications').insert({
324	              user_id: company.owner_id,
325	              type: 'status_change',
326	              title: 'Freela aceitou o turno',
327	              message: 'Um freela aceitou seu convite de turno.',
328	              link: `/company/candidates`,
329	            });
330	
331	            if (notifErr) {
332	              logError('shiftInvite.respondToInvite.notif', notifErr);
333	            }
334	          }
335	        }
336	      }
337	
338	      return { success: true };
339	    } catch (err) {
340	      logError('shiftInvite.respondToInvite', err);
341	      return {
342	        success: false,
343	        error: err instanceof Error ? err.message : 'Erro inesperado.',
344	      };
345	    }
346	  },
347	
348	  // -------------------------------------------------------------------------
349	  // Listagem de convites pendentes (worker)
350	  // -------------------------------------------------------------------------
351	
352	  /**
353	   * Lista convites de turno pendentes ('invited') do worker autenticado.
354	   * Inclui dados do job e da empresa para a aba "Convites".
355	   */
356	  async listPendingInvites(): Promise<Application[]> {
357	    try {
358	      const {
359	        data: { user },
360	      } = await supabase.auth.getUser();
361	      if (!user) return [];
362	
363	      const { data, error } = await supabase
364	        .from('applications')
365	        .select(
366	          `
367	          *,
368	          job:jobs (
369	            id,
370	            title,
371	            description,
372	            location,
373	            start_date,
374	            work_start_time,
375	            work_end_time,
376	            budget,
377	            has_lunch,
378	            company_id,
379	            company:companies (
380	              id,
381	              name,
382	              logo_url,
383	              rating_average
384	            )
385	          )
386	        `,
387	        )
388	        .eq('worker_id', user.id)
389	        .eq('status', 'invited')
390	        .order('invited_by_company_at', { ascending: false });
391	
392	      if (error) {
393	        logError('shiftInvite.listPendingInvites', error);
394	        return [];
395	      }
396	
397	      return (data ?? []) as Application[];
398	    } catch (err) {
399	      logError('shiftInvite.listPendingInvites', err);
400	      return [];
401	    }
402	  },
403	
404	  /**
405	   * Lista convites enviados por uma empresa para um job específico.
406	   * Para o operador acompanhar respostas.
407	   */
408	  async listInvitesByJob(jobId: string): Promise<Application[]> {
409	    try {
410	      const { data, error } = await supabase
411	        .from('applications')
412	        .select(
413	          `
414	          *,
415	          worker:workers (
416	            id,
417	            full_name,
418	            avatar_url,
419	            photo_url,
420	            primary_role,
421	            rating_average
422	          )
423	        `,
424	        )
425	        .eq('job_id', jobId)
426	        .not('invited_by_company_at', 'is', null)
427	        .order('invited_by_company_at', { ascending: false });
428	
429	      if (error) {
430	        logError('shiftInvite.listInvitesByJob', error);
431	        return [];
432	      }
433	
434	      return (data ?? []) as Application[];
435	    } catch (err) {
436	      logError('shiftInvite.listInvitesByJob', err);
437	      return [];
438	    }
439	  },
440	};
