1	/**
2	 * useTeamConnections — hook de UI para o roster "minha equipe" e "minhas lojas".
3	 *
4	 * Dois modos de uso:
5	 *   - papel 'company': lista equipe aceita + conexões pendentes da empresa.
6	 *   - papel 'worker':  lista lojas aceitas + convites de equipe pendentes.
7	 *
8	 * Padrão do projeto: useState + useEffect + supabase direto (Art. 5 — sem React Query).
9	 */
10	
11	import { useState, useEffect, useCallback } from 'react';
12	import { useNavigate } from 'react-router-dom';
13	import { supabase } from '../lib/supabase';
14	import { TeamConnectionService } from '../services/teamConnectionService';
15	import { useToast } from '../contexts/ToastContext';
16	import type { TeamConnection, TeamMember, MyStore, TeamConnectionSource } from '../types';
17	
18	// ---------------------------------------------------------------------------
19	// Hook para EMPRESA — gerenciar "minha equipe"
20	// ---------------------------------------------------------------------------
21	
22	export interface UseCompanyTeamResult {
23	  /** Membros aceitos (com perfil do worker). */
24	  teamMembers: TeamMember[];
25	  /** Convites de equipe pendentes (empresa enviou, aguarda worker). */
26	  pendingConnections: TeamConnection[];
27	  loading: boolean;
28	  /** company_id real da empresa autenticada (necessário para gerar link de convite estável). */
29	  companyId: string;
30	  /** Adicionar worker via QR/link/phone. */
31	  addWorker: (workerId: string, source: TeamConnectionSource) => Promise<boolean>;
32	  /** Recarregar dados. */
33	  refresh: () => void;
34	}
35	
36	export function useCompanyTeam(): UseCompanyTeamResult {
37	  const [teamMembers, setTeamMembers] = useState<TeamMember[]>([]);
38	  const [pendingConnections, setPendingConnections] = useState<TeamConnection[]>([]);
39	  const [companyId, setCompanyId] = useState<string>('');
40	  const [loading, setLoading] = useState(true);
41	  const navigate = useNavigate();
42	  const { addToast } = useToast();
43	
44	  const load = useCallback(async () => {
45	    const {
46	      data: { user },
47	    } = await supabase.auth.getUser();
48	    if (!user) {
49	      navigate('/login');
50	      return;
51	    }
52	
53	    setLoading(true);
54	    const { data: company } = await supabase
55	      .from('companies')
56	      .select('id')
57	      .eq('owner_id', user.id)
58	      .maybeSingle();
59	    if (company?.id) setCompanyId(company.id as string);
60	
61	    const [members, all] = await Promise.all([
62	      TeamConnectionService.listTeamMembers(),
63	      TeamConnectionService.listAllConnections(),
64	    ]);
65	
66	    setTeamMembers(members);
67	    setPendingConnections(all.filter((c) => c.status === 'pending'));
68	    setLoading(false);
69	  }, [navigate]);
70	
71	  useEffect(() => {
72	    let active = true;
73	    void (async () => {
74	      const {
75	        data: { user },
76	      } = await supabase.auth.getUser();
77	      if (!user) {
78	        navigate('/login');
79	        return;
80	      }
81	
82	      setLoading(true);
83	      const { data: company } = await supabase
84	        .from('companies')
85	        .select('id')
86	        .eq('owner_id', user.id)
87	        .maybeSingle();
88	      if (active && company?.id) setCompanyId(company.id as string);
89	
90	      const [members, all] = await Promise.all([
91	        TeamConnectionService.listTeamMembers(),
92	        TeamConnectionService.listAllConnections(),
93	      ]);
94	
95	      if (!active) return;
96	      setTeamMembers(members);
97	      setPendingConnections(all.filter((c) => c.status === 'pending'));
98	      setLoading(false);
99	    })();
100	    return () => {
101	      active = false;
102	    };
103	  }, [navigate]);
104	
105	  const addWorker = useCallback(
106	    async (workerId: string, source: TeamConnectionSource): Promise<boolean> => {
107	      const result = await TeamConnectionService.addToTeam(workerId, source);
108	
109	      if (result.alreadyExists) {
110	        addToast('Este freela já está na sua equipe.', 'info');
111	        return true;
112	      }
113	      if (result.error) {
114	        addToast(result.error, 'error');
115	        return false;
116	      }
117	
118	      addToast('Convite de equipe enviado! Aguardando aceite do freela.', 'success');
119	      load();
120	      return true;
121	    },
122	    [addToast, load],
123	  );
124	
125	  return { teamMembers, pendingConnections, loading, companyId, addWorker, refresh: load };
126	}
127	
128	// ---------------------------------------------------------------------------
129	// Hook para WORKER — "minhas lojas" + convites de equipe pendentes
130	// ---------------------------------------------------------------------------
131	
132	export interface UseWorkerStoresResult {
133	  /** Empresas aceitas ("minhas lojas"). */
