170	    setLoading(false);
171	  }, [navigate]);
172	
173	  useEffect(() => {
174	    let active = true;
175	    void (async () => {
176	      const {
177	        data: { user },
178	      } = await supabase.auth.getUser();
179	      if (!user) {
180	        navigate('/login');
181	        return;
182	      }
183	
184	      setLoading(true);
185	      const [stores, pending] = await Promise.all([
186	        TeamConnectionService.listMyStores(),
187	        TeamConnectionService.listPendingConnections(),
188	      ]);
189	
190	      if (!active) return;
191	      setMyStores(stores);
192	      setPendingConnections(pending);
193	      setLoading(false);
194	    })();
195	    return () => {
196	      active = false;
197	    };
198	  }, [navigate]);
199	
200	  const acceptConnection = useCallback(
201	    async (connectionId: string): Promise<boolean> => {
202	      const result = await TeamConnectionService.acceptConnection(connectionId);
203	      if (result.error) {
204	        addToast(result.error, 'error');
205	        return false;
206	      }
207	      addToast('Você agora faz parte da equipe!', 'success');
208	      load();
209	      return true;
210	    },
211	    [addToast, load],
212	  );
213	
214	  const blockConnection = useCallback(
215	    async (connectionId: string): Promise<boolean> => {
216	      const result = await TeamConnectionService.blockConnection(connectionId);
217	      if (result.error) {
218	        addToast(result.error, 'error');
219	        return false;
220	      }
221	      addToast('Conexão removida.', 'success');
222	      load();
223	      return true;
224	    },
225	    [addToast, load],
226	  );
227	
228	  return {
229	    myStores,
230	    pendingConnections,
231	    loading,
232	    acceptConnection,
233	    blockConnection,
234	    refresh: load,
235	  };
236	}
