22	export interface UseWorkerInvitesResult {
23	  /** Convites de turno pendentes (status='invited'). */
24	  pendingInvites: Application[];
25	  loading: boolean;
26	  /** ID do convite sendo processado (para loading state no botão). */
27	  respondingId: string | null;
28	  /** Aceitar ou recusar um convite. */
29	  respond: (applicationId: string, response: InvitationResponse) => Promise<boolean>;
30	  /** Recarregar convites. */
31	  refresh: () => void;
32	}
33	
34	export function useWorkerInvites(): UseWorkerInvitesResult {
35	  const [pendingInvites, setPendingInvites] = useState<Application[]>([]);
36	  const [loading, setLoading] = useState(true);
37	  const [respondingId, setRespondingId] = useState<string | null>(null);
38	  const navigate = useNavigate();
39	  const { addToast } = useToast();
40	
41	  const load = useCallback(async () => {
42	    const {
43	      data: { user },
44	    } = await supabase.auth.getUser();
45	    if (!user) {
46	      navigate('/login');
47	      return;
48	    }
49	
50	    setLoading(true);
51	    const invites = await ShiftInviteService.listPendingInvites();
52	    setPendingInvites(invites);
53	    setLoading(false);
54	  }, [navigate]);
55	
56	  useEffect(() => {
57	    let active = true;
58	    void (async () => {
59	      const {
60	        data: { user },
61	      } = await supabase.auth.getUser();
62	      if (!user) {
63	        navigate('/login');
64	        return;
65	      }
66	
67	      setLoading(true);
68	      const invites = await ShiftInviteService.listPendingInvites();
69	      if (!active) return;
70	      setPendingInvites(invites);
71	      setLoading(false);
72	    })();
73	    return () => {
74	      active = false;
75	    };
76	  }, [navigate]);
77	
78	  const respond = useCallback(
79	    async (applicationId: string, response: InvitationResponse): Promise<boolean> => {
80	      setRespondingId(applicationId);
81	      const result = await ShiftInviteService.respondToInvite(applicationId, response);
82	      setRespondingId(null);
83	
84	      if (result.error) {
85	        addToast(result.error, 'error');
86	        return false;
87	      }
88	
89	      if (response === 'accepted') {
90	        addToast('Turno confirmado! Bom trabalho.', 'success');
91	      } else {
92	        addToast('Convite recusado.', 'info');
93	      }
94	
95	      // Recarregar lista (o convite respondido some dos pendentes)
96	      load();
97	      return true;
98	    },
99	    [addToast, load],
100	  );
101	
102	  return { pendingInvites, loading, respondingId, respond, refresh: load };
103	}
