115	  /** Convidar worker da equipe para o turno. */
116	  invite: (workerId: string, opts?: { expiresInHours?: number; message?: string }) => Promise<boolean>;
117	  /** Recarregar convites do job. */
118	  refresh: () => void;
119	}
