125	  const navigate = useNavigate();
126	  const { addToast } = useToast();
127	
128	  const load = useCallback(async () => {
129	    const {
130	      data: { user },
131	    } = await supabase.auth.getUser();
132	    if (!user) {
133	      navigate('/login');
134	      return;
135	    }
136	
137	    setLoading(true);
138	    const list = await ShiftInviteService.listInvitesByJob(jobId);
139	    setInvites(list);
140	    setLoading(false);
141	  }, [jobId, navigate]);
142	
143	  useEffect(() => {
144	    let active = true;
145	    void (async () => {
146	      const {
147	        data: { user },
148	      } = await supabase.auth.getUser();
149	      if (!user) {
150	        navigate('/login');
151	        return;
152	      }
153	
154	      setLoading(true);
155	      const list = await ShiftInviteService.listInvitesByJob(jobId);
156	      if (!active) return;
157	      setInvites(list);
158	      setLoading(false);
159	    })();
160	    return () => {
161	      active = false;
162	    };
163	  }, [jobId, navigate]);
164	
165	  const invite = useCallback(
166	    async (
167	      workerId: string,
168	      opts: { expiresInHours?: number; message?: string } = {},
169	    ): Promise<boolean> => {
170	      setInvitingWorkerId(workerId);
171	      const result = await ShiftInviteService.inviteWorkerToShift(jobId, workerId, opts);
172	      setInvitingWorkerId(null);
173	
174	      if (result.alreadyInvited) {
175	        addToast('Este freela já foi convidado para este turno.', 'info');
176	        return true;
177	      }
178	      if (result.error) {
179	        addToast(result.error, 'error');
180	        return false;
181	      }
182	
183	      addToast('Convite enviado com sucesso!', 'success');
184	      load();
185	      return true;
186	    },
187	    [jobId, addToast, load],
188	  );
189	
190	  return { invites, loading, invitingWorkerId, invite, refresh: load };
191	}
